import{_ as l,o as e,c as a,a2 as o}from"./chunks/framework.DSQXGnvq.js";const p=JSON.parse('{"title":"版本日志","description":"","frontmatter":{},"headers":[],"relativePath":"news.md","filePath":"news.md"}'),t={name:"news.md"};function r(n,i,c,d,s,h){return e(),a("div",null,[...i[0]||(i[0]=[o('<h1 id="版本日志" tabindex="-1">版本日志 <a class="header-anchor" href="#版本日志" aria-label="Permalink to &quot;版本日志&quot;">​</a></h1><h2 id="v1-6-0-开发版本" tabindex="-1">V1.6.0（开发版本） <a class="header-anchor" href="#v1-6-0-开发版本" aria-label="Permalink to &quot;V1.6.0（开发版本）&quot;">​</a></h2><ul><li><strong>KiCadTools</strong>：概念验证模块，可读取 KiCad 6 的 <code>.kicad_sch</code> 原理图文件并生成网表。<em>此模块可对 KiCad 原理图进行任意处理。目前位于源码中，但可能成为独立项目。</em> 对 PySpice 而言，它提供了一种灵活的方式——在 KiCad 中绘制电路，在不使用 KiCad 网表导出功能的情况下即可生成网表。</li></ul><h2 id="v1-5-0-正式版-2021-05-15" tabindex="-1">V1.5.0（正式版）2021-05-15 <a class="header-anchor" href="#v1-5-0-正式版-2021-05-15" aria-label="Permalink to &quot;V1.5.0（正式版）2021-05-15&quot;">​</a></h2><ul><li>支持 Ngspice 最高至 34 版</li><li>将自定义双下划线属性 <code>__dunder__</code> 重命名为 <code>CONSTANT</code> 或 <code>_private</code> 类属性</li><li>修复文档中的拼写错误（感谢 endolith 和 brollb）</li><li>添加 DC 温度扫描支持 #272（感谢 Fatsie）</li><li>PWL 支持改进 #271（感谢 Fatsie）</li><li>创建温度扫描向量时分配单位 #263（感谢 ARF1）</li><li>通过释放 ngspice 命令日志防止内存泄漏 #260（感谢 ARF1）</li><li>性能优化：批量发送多个 alter 命令 #259（感谢 ARF1）</li><li>添加 spice 库支持 #258（感谢 Fatsie）</li><li>允许为 PWL 指定 DC 值 #257（感谢 Fatsie）</li><li>支持 <code>.nodeset</code> 类型初始条件 #256（感谢 Fatsie）</li><li>修复精度问题 #254（感谢 sotw1957）</li><li>改进在大量 SPICE 模型中使用的体验 #249（感谢 xesscorp）</li><li>修复网表解析时的参数合并错误 #245（感谢 cyber-g）</li><li>Unit：添加 Pickle 支持</li><li>引入 #136 的解析器代码（感谢 jmgc，尚未合并）</li><li>Unit：添加 <code>np.mean</code></li></ul><h2 id="v1-4-3-2020-07-04" tabindex="-1">V1.4.3 2020-07-04 <a class="header-anchor" href="#v1-4-3-2020-07-04" aria-label="Permalink to &quot;V1.4.3 2020-07-04&quot;">​</a></h2><p>感谢 @stuarteberg Stuart Berg 的大量工作，Ngspice 和 PySpice 现已可通过 Anaconda（conda-forge）在 Windows、OSX 和 Linux 平台上使用。借助 conda-forge 持续集成平台，我们可以在这些平台上自动运行单元测试和示例。</p><ul><li>PySpice 现在以 conda-forge 包和 PyPI wheel 的形式发布</li><li>添加安装后工具，用于在 Windows 上下载 Ngspice DLL 并检查安装</li><li>该工具还可下载示例和 Ngspice PDF 手册</li><li>Linux 和 OSX 上，Ngspice 包现可从 Anaconda（conda-forge）获取</li><li>更新了 Linux 安装文档，主流发行版现已提供 ngspice 共享包</li><li>添加前端网站，使旧版本文档可在线访问</li><li>修复并重新构建所有示例</li><li>示例现以 Python 文件和 Jupyter notebook 两种形式提供</li><li>支持 NgSpice 32 API（无变化）</li><li>修复若干问题：NonLinearVoltageSource、Unicode 问题（°C）、ffi_string_utf8、OSX 日志格式化等</li><li>将 cir2py 转为入口点以支持所有平台</li><li>更新示例中 Matplotlib 子图</li><li>添加单位示例、NMOS 示例 #221</li></ul><h2 id="v1-4-0-2020-05-05" tabindex="-1">V1.4.0 2020-05-05 <a class="header-anchor" href="#v1-4-0-2020-05-05" aria-label="Permalink to &quot;V1.4.0 2020-05-05&quot;">​</a></h2><p>此版本因 Windows 支持存在问题被撤回。</p><ul><li>修复 NgSpice 共享的 <code>setlocale(LC_NUMERIC, &quot;C&quot;);</code> 问题 #172</li><li>修复新 Ngspice 语法中的 <code>AC AC_MAG AC_PASAE SIN</code></li><li>修复多种设备和 API 问题</li><li>支持 NgSpice 31 API</li><li>添加多项分析与参数支持（pole-zero、noise、distorsion、transfer-function、<code>.measure</code>）</li><li>添加 Xyce Mosfet nfin #177</li></ul><h2 id="v1-3-2-2019-03-11" tabindex="-1">V1.3.2 2019-03-11 <a class="header-anchor" href="#v1-3-2-2019-03-11" aria-label="Permalink to &quot;V1.3.2 2019-03-11&quot;">​</a></h2><ul><li>支持 Ngspice 30 和 Xyce 6.10</li><li>修复 Windows 10 上的 NgSpice 和 Xyce 支持</li><li>其他 bug 修复</li></ul><h2 id="v1-2-0-2018-06-07" tabindex="-1">V1.2.0 2018-06-07 <a class="header-anchor" href="#v1-2-0-2018-06-07" aria-label="Permalink to &quot;V1.2.0 2018-06-07&quot;">​</a></h2><ul><li>初步支持 Xyce 模拟器。Xyce 是 Sandia 国家实验室开发的 SPICE 兼容高性能模拟电路模拟器，适合工业和研究用途</li><li>修复 OSX 支持</li><li>拆分 G 器件</li><li>部分实现 <code>A</code> XSPICE 器件</li><li>实现缺失的传输线器件</li><li>实现高级电流源（<strong>注意：部分类已重命名！</strong>）</li><li>实现节点关键字参数</li><li>实现原始 SPICE 透传</li><li>实现内部参数访问</li><li>实现接地节点缺失检查</li><li>实现禁用元素和克隆网表的功能</li><li>改进 SPICE 解析器和单位支持</li><li>修复多项问题：节点顺序、设备快捷方式、BJT 模型参数、子电路嵌套</li><li>将文档生成器迁移至 Pyterate</li></ul><h2 id="v1-1-0-2017-09-06" tabindex="-1">V1.1.0 2017-09-06 <a class="header-anchor" href="#v1-1-0-2017-09-06" aria-label="Permalink to &quot;V1.1.0 2017-09-06&quot;">​</a></h2><ul><li>增强共享模式</li><li>共享模式在 Linux 上设为默认</li></ul><h2 id="v1-0-0-2017-09-06" tabindex="-1">V1.0.0 2017-09-06 <a class="header-anchor" href="#v1-0-0-2017-09-06" aria-label="Permalink to &quot;V1.0.0 2017-09-06&quot;">​</a></h2><ul><li>版本升至 v1.0.0</li><li>支持 Windows 平台的 Ngspice 共享模式</li><li>修复共享模式</li><li>修复并完善 Spice 解析器</li></ul><h2 id="v0-4-2" tabindex="-1">V0.4.2 <a class="header-anchor" href="#v0-4-2" aria-label="Permalink to &quot;V0.4.2&quot;">​</a></h2><ul><li>修复 Spice 解析器小写器件前缀问题</li></ul><h2 id="v0-4-0-2017-07-31" tabindex="-1">V0.4.0 2017-07-31 <a class="header-anchor" href="#v0-4-0-2017-07-31" aria-label="Permalink to &quot;V0.4.0 2017-07-31&quot;">​</a></h2><ul><li>清理 Git 仓库</li><li>改进文档生成器和单位支持</li><li>单位支持国际单位制</li><li>添加 Simulation 实例到 Analysis 类</li><li>重构仿真参数为类</li></ul><h2 id="v0-3-2-2017-02-22" tabindex="-1">V0.3.2 2017-02-22 <a class="header-anchor" href="#v0-3-2-2017-02-22" aria-label="Permalink to &quot;V0.3.2 2017-02-22&quot;">​</a></h2><ul><li>修复 CCCS 和 CCVS</li></ul><h2 id="v0-3-1-2017-02-22" tabindex="-1">V0.3.1 2017-02-22 <a class="header-anchor" href="#v0-3-1-2017-02-22" aria-label="Permalink to &quot;V0.3.1 2017-02-22&quot;">​</a></h2><ul><li>修复 ngspice 共享</li></ul><h2 id="v0-3-0-2015-12-08" tabindex="-1">V0.3.0 2015-12-08 <a class="header-anchor" href="#v0-3-0-2015-12-08" aria-label="Permalink to &quot;V0.3.0 2015-12-08&quot;">​</a></h2><ul><li>添加 NgSpice 共享仿真模式示例</li><li>完善 Spice 网表解析器并添加示例</li><li>cir2py 程序可将电路文件转换为 Python</li></ul><h2 id="v0-2014-03-21" tabindex="-1">V0 2014-03-21 <a class="header-anchor" href="#v0-2014-03-21" aria-label="Permalink to &quot;V0 2014-03-21&quot;">​</a></h2><p>项目启动</p>',31)])])}const P=l(t,[["render",r]]);export{p as __pageData,P as default};
